  const map = {};
  Object.keys(BY_PATH).forEach(p => {
    map[p] = BY_PATH[p];
    const fname = p.split('/').pop();
    if (fname) {
      map[fname] = BY_PATH[p];
      map[fname.trim()] = BY_PATH[p];
      map[fname.toLowerCase()] = BY_PATH[p];
    }
  });
  META.forEach(m => {
    const src = BY_PATH[m.img];
    if (src) {
      map[m.name] = src;
      map[m.name.toLowerCase()] = src;
    }
  });
  EXTRA.forEach(ep => {
    const src = BY_PATH[ep.path];
    if (src && Array.isArray(ep.names)) {
      ep.names.forEach(n => {
        map[n] = src;
        map[String(n).toLowerCase()] = src;
      });
    }
  });
  window.TEACHER_IMAGES = map;
